        },
        {
            "field": "wacc_components",
            "sheet": "估值假设",
            "cell_or_range": "B12:B22",
            "role": "formula",
            "source_ids": (field_sources.get("wacc") or {}).get("source_ids")
            or [(field_sources.get("wacc") or {}).get("source_id")],
            "scenario": "base",
            "notes": "WACC组成及计算单元格",
        },
        {
            "field": "equity_bridge.share_classes",
            "sheet": "股本与市值桥",
